{"tool": "writeProjectFile", "params": {"content": "import { createHmac, timingSafeEqual, createHash } from 'node:crypto';
import { readFile, writeFile } from 'node:fs/promises';

export type HelloEnvelope = { deviceId: string; ts: number; nonce: string; payload: unknown; sig: string };

export function canonicalize(obj: unknown): string {
  const sort = (o: any): any => {
    if (o === null || typeof o !== 'object') return o;
    if (Array.isArray(o)) return o.map(sort);
    return Object.fromEntries(
      Object.entries(o).sort(([a], [b]) => a.localeCompare(b)).map(([k, v]) => [k, sort(v)])
    );
  };
  return JSON.stringify(sort(obj));
}

export async function isFreshNonce(nonce: string, ts: number): Promise<boolean> {
  const now = Date.now();
  if (Math.abs(now - ts) > 300000) return false;

  try {
    const cache = JSON.parse(await readFile('data/.bridge-nonce-cache', 'utf8'));
    if (cache[nonce]) return false;
    cache[nonce] = now;
    await writeFile('data/.bridge-nonce-cache', JSON.stringify(cache));
    return true;
  } catch { return true; }
}

export function verifyHelloSignature(envelope: HelloEnvelope, secret: string): { ok: boolean; sessionId?: string; reason?: string } {
  if (Buffer.from(secret).length < 32) throw new Error('Secret must be at least 32 bytes');

  const payload = JSON.stringify({ deviceId: envelope.deviceId, ts: envelope.ts, nonce: envelope.nonce, payload: envelope.payload });
  const hmac = createHmac('sha256', secret).update(payload).digest('hex');

  if (!timingSafeEqual(Buffer.from(envelope.sig), Buffer.from(hmac))) {
    return { ok: false, reason: 'Invalid signature' };
  }

  return { ok: true, sessionId: createHash('sha256').update(envelope.deviceId + envelope.nonce).digest('hex') };
}
